import{_ as l,q as s,o as e,x as c}from"./chunks/framework.B2naXvmR.js";const h=JSON.parse('{"title":"","description":"","frontmatter":{"home":true,"layout":"home"},"headers":[],"relativePath":"index.md","filePath":"index.md"}'),t={name:"index.md"};function a(o,i,d,n,r,v){return e(),s("div",null,[...i[0]||(i[0]=[c('<nav class="section-nav"><div class="container"><ul><li><a href="#top">TOP</a></li><li><a href="#model">一貫支援モデル</a></li><li><a href="#services">コンサルティング領域</a></li><li><a href="#flow">導入の流れ</a></li><li><a href="#company">会社情報</a></li></ul></div></nav><div id="top"></div><section class="hero"><div class="container hero-inner"><h1> 世界最先端医療技術の日本導入を一貫支援する<br>コンサルティングプラットフォーム </h1><p class="hero-lead"> 検査・薬剤・医療機器・デジタル健診――世界の医療イノベーションを評価し、導入し、現場に定着させる総合支援。 </p><p class="hero-note"> ※医師プラットフォーム MedPeer で培った知見を背景としたコンサルティングモデルに基づくサービス </p></div></section><section class="section" id="model"><div class="container"><h2 class="section-title"> 一貫支援モデル「選定 → 導入設計 → 定着支援」 </h2><p class="section-intro"> すべてのプロジェクトを、世界の医療技術の「選定」、現場に合わせた「導入設計」、導入後の「定着支援」という3つのステップで支援します。 </p><div class="model-grid"><article class="model-item"><div class="model-icon">①</div><div><h3>選定（Discovery）</h3><p> 世界の医療技術・検査・薬剤・デバイスのスクリーニングと比較評価。臨床効果・安全性・費用・規制適合性を踏まえた導入候補の選定。 </p></div></article><article class="model-item"><div class="model-icon">②</div><div><h3>導入設計（Design）</h3><p> 医療機関や施設の実情に合わせた運用フロー・スタッフ体制・役割分担・料金設計の策定。検査・薬剤・デバイスを組み合わせた提供モデルの設計。 </p></div></article><article class="model-item"><div class="model-icon">③</div><div><h3>定着支援（Support）</h3><p> トレーニング・教育資料の提供、症例ベースの相談、運用状況レビューと改善提案による継続的な定着支援。 </p></div></article></div></div></section><section class="section" id="services"><div class="container"><h2 class="section-title">コンサルティング領域</h2><p class="section-intro"> プレシジョンメディシン、国際薬剤アクセス、スマート健診・医療デバイスの三領域を中心に、世界の医療技術の日本導入を一貫支援します。 </p><div class="services-grid"><article class="service-card"><h3>プレシジョンメディシン導入支援</h3><ul><li> がんゲノム検査・マルチキャンサースクリーニング検査の導入評価と実装支援。 </li><li>検査フロー設計、プレシジョンレポート運用モデルの構築。</li><li> 医師・スタッフ向け教育プログラム、患者説明資料・FAQ の整備。 </li><li>症例カンファレンス支援を通じた臨床現場での活用促進。</li></ul></article><article class="service-card"><h3>国際薬剤アクセスコンサル</h3><ul><li> 分子標的薬・免疫療法など海外薬剤の情報リサーチと比較評価。 </li><li> 承認状況・エビデンス・費用・リスク・規制に基づくアクセススキームの検討。 </li><li> 症例ごとの候補薬剤整理と費用・期間・リスクの見える化支援。 </li><li><strong>医師個人輸入のための発注・申請・通関手続きのサポート。</strong></li></ul></article><article class="service-card"><h3>スマート健診・医療デバイス導入支援</h3><ul><li> AI口腔カメラ、補聴ソリューション、自動検査機などの選定・組み合わせ設計。 </li><li> 高齢者施設・在宅医療・離島医療など用途別の運用モデル構築。 </li><li> 受付〜実施〜記録〜フォローまでのフロー設計とスタッフ教育。 </li><li><strong>営業・薬事関連サポート</strong>を含めたトータル支援と導入後の改善提案。 </li></ul></article></div></div></section><section class="section" id="flow"><div class="container"><h2 class="section-title">導入の流れ</h2><p class="section-intro"> 初回相談から定着支援まで、共通のプロセスでプロジェクトを進行します。 </p><ol class="flow-steps"><li> 初回相談・現状整理（診療内容・対象患者・導入目的のヒアリング）。 </li><li>関連する検査・薬剤・デバイス・海外事例のリサーチと候補整理。</li><li> 効果・安全性・費用・運用負荷・規制の観点からの比較評価と選定レポート共有。 </li><li> 導入フロー・体制・タイムライン・価格設計を含む実行計画の策定。 </li><li>スタッフ向けトレーニングと一部症例・一部施設での試験稼働。</li><li>実績データを踏まえたレビューと、定着・拡大に向けた改善提案。</li></ol></div></section><section class="section" id="company"><div class="container"><h2 class="section-title">会社情報</h2><dl class="company-grid"><div><dt>社名</dt><dd>GenoStar Inc.</dd></div><div><dt>事業内容</dt><dd> 医療技術の評価・比較、導入フローの設計、<br> プレシジョンメディシン導入支援、国際薬剤アクセスコンサル、<br> スマート健診・医療デバイス導入支援 等。 </dd></div><div><dt>ミッション</dt><dd> 世界最先端医療技術へのアクセスを最適化し、患者と医療者が「必要なときに、必要な医療」に近づける環境の実現。 </dd></div></dl><p class="company-note"> 医師向けプラットフォーム事業で培われた知見とネットワークを背景に、臨床現場の課題に即した医療技術導入コンサルティングサービスを展開しています。 </p></div></section><footer class="site-footer"><div class="container">© GenoStar Inc.</div></footer>',8)])])}const m=l(t,[["render",a]]);export{h as __pageData,m as default};
